from taf.internal.core import Factory
from .managed_ssh_connection_factory import ManagedSshConnectionFactorySelector
from taf.internal.execution.ssh import SshExecutor


class SshExecutorFactory(Factory):
    _product_class = SshExecutor
    _optional_parameters = {"sudo_password"}

    def _build_arguments(self, configuration, existing_arguments,
                         resulting_arguments):
        super(SshExecutorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments[
            'managed_ssh_connection'] = ManagedSshConnectionFactorySelector().create(  # noqa: E501
            configuration=configuration['ssh'],
            existing_arguments={})
